CREATE TABLE public.site_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('home_section','banner','faq','testimonial','contact','page','navigation','footer','location_page','redirect')), draft jsonb NOT NULL DEFAULT '{}', published jsonb, revision integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
GRANT SELECT ON public.site_content TO anon,authenticated; GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public published content" ON public.site_content FOR SELECT TO anon,authenticated USING(published IS NOT NULL);
CREATE POLICY "content staff read drafts" ON public.site_content FOR SELECT TO authenticated USING(public.has_permission('content.manage'));
CREATE TABLE public.content_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES public.site_content(id), revision integer NOT NULL, payload jsonb NOT NULL, action text NOT NULL, actor_id uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.content_revisions TO authenticated; GRANT ALL ON public.content_revisions TO service_role;
ALTER TABLE public.content_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "content staff history" ON public.content_revisions FOR SELECT TO authenticated USING(public.has_permission('content.manage'));
CREATE TABLE public.plan_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text UNIQUE NOT NULL CHECK(key IN ('free','premium','platinum')), name text NOT NULL, price_minor integer NOT NULL DEFAULT 0 CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'INR', period_days integer NOT NULL DEFAULT 30 CHECK(period_days BETWEEN 1 AND 366), entitlements jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.plan_definitions TO anon,authenticated; GRANT ALL ON public.plan_definitions TO service_role; ALTER TABLE public.plan_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public configured plans" ON public.plan_definitions FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY "finance reads plans" ON public.plan_definitions FOR SELECT TO authenticated USING(public.has_permission('commerce.manage'));
CREATE TABLE public.business_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), plan_id uuid NOT NULL REFERENCES public.plan_definitions(id), status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','active','cancelled','expired','payment_failed')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, cancel_at_end boolean NOT NULL DEFAULT false, reason text NOT NULL, actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
GRANT SELECT ON public.business_subscriptions TO authenticated; GRANT ALL ON public.business_subscriptions TO service_role; ALTER TABLE public.business_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "subscription scoped read" ON public.business_subscriptions FOR SELECT TO authenticated USING(public.has_permission('commerce.manage',business_id) OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE TABLE public.commercial_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES public.business_subscriptions(id), reference text NOT NULL UNIQUE, amount_minor integer NOT NULL CHECK(amount_minor>=0), currency text NOT NULL DEFAULT 'INR', status text NOT NULL CHECK(status IN ('unpaid','paid','failed','void')), method text NOT NULL CHECK(method IN ('manual','provider')), external_reference text NOT NULL DEFAULT '', reason text NOT NULL, recorded_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commercial_records TO authenticated; GRANT ALL ON public.commercial_records TO service_role; ALTER TABLE public.commercial_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "invoice scoped read" ON public.commercial_records FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.business_subscriptions s WHERE s.id=subscription_id));
CREATE TABLE public.sponsored_placements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), city text NOT NULL, category text NOT NULL DEFAULT '', placement text NOT NULL CHECK(placement IN ('search','home','category')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('active','paused','expired')), creative text NOT NULL, approved boolean NOT NULL DEFAULT false, terms text NOT NULL, budget_minor integer NOT NULL DEFAULT 0 CHECK(budget_minor>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
GRANT SELECT ON public.sponsored_placements TO authenticated; GRANT ALL ON public.sponsored_placements TO service_role; ALTER TABLE public.sponsored_placements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "placement scoped read" ON public.sponsored_placements FOR SELECT TO authenticated USING(public.has_permission('commerce.manage',business_id) OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE TABLE public.merchant_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), title text NOT NULL, eligibility text NOT NULL, terms text NOT NULL, city text NOT NULL, locality text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, usage_limit integer NOT NULL DEFAULT 0 CHECK(usage_limit>=0), redemption_mode text NOT NULL DEFAULT 'merchant_confirmation' CHECK(redemption_mode='merchant_confirmation'), approved boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','expired')), CHECK(ends_at>starts_at));
GRANT SELECT ON public.merchant_offers TO anon,authenticated; GRANT ALL ON public.merchant_offers TO service_role; ALTER TABLE public.merchant_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public current offers" ON public.merchant_offers FOR SELECT TO anon,authenticated USING(approved AND status='active' AND starts_at<=now() AND ends_at>now() AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.status='approved' AND b.archived_at IS NULL AND b.city=city));
CREATE POLICY "offer scoped read" ON public.merchant_offers FOR SELECT TO authenticated USING(public.has_permission('commerce.manage',business_id) OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE TABLE public.offer_redemptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES public.merchant_offers(id), reference uuid NOT NULL UNIQUE, recorded_by uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.offer_redemptions TO authenticated; GRANT ALL ON public.offer_redemptions TO service_role; ALTER TABLE public.offer_redemptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "merchant reads redemptions" ON public.offer_redemptions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.merchant_offers o JOIN public.businesses b ON b.id=o.business_id WHERE o.id=offer_id AND (b.owner_id=auth.uid() OR public.has_permission('commerce.manage',b.id))));
CREATE TABLE public.placement_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), placement_id uuid NOT NULL REFERENCES public.sponsored_placements(id), event_key uuid NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('impression','click','enquiry')), lead_id uuid REFERENCES public.leads(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.placement_events TO authenticated; GRANT ALL ON public.placement_events TO service_role; ALTER TABLE public.placement_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "placement event scoped read" ON public.placement_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.sponsored_placements p WHERE p.id=placement_id));
ALTER TABLE public.businesses ADD COLUMN public_slug text;
UPDATE public.businesses SET public_slug=coalesce(nullif(trim(both '-' from regexp_replace(lower(name||'-'||city),'[^a-z0-9]+','-','g')),''),'business')||'-'||id::text;
CREATE UNIQUE INDEX businesses_public_slug_unique ON public.businesses(public_slug);
CREATE OR REPLACE FUNCTION public.guard_business_slug() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN NEW.public_slug:=OLD.public_slug; ELSE NEW.public_slug:=coalesce(nullif(trim(both '-' from regexp_replace(lower(NEW.name||'-'||NEW.city),'[^a-z0-9]+','-','g')),''),'business')||'-'||NEW.id::text; END IF; RETURN NEW; END; $$;
CREATE TRIGGER immutable_business_slug BEFORE INSERT OR UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.guard_business_slug();
CREATE OR REPLACE FUNCTION public.content_permission() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_permission('content.manage'); $$;
CREATE OR REPLACE FUNCTION public.save_site_content(payload jsonb, publish_content boolean DEFAULT false, decision_reason text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; rev integer; k text:=payload->>'kind'; c text:=coalesce(payload->>'city',''); cat text:=coalesce(payload->>'category',''); label text:=lower(payload->>'title'); matches integer; BEGIN
IF NOT public.content_permission() THEN RAISE EXCEPTION 'Content management denied'; END IF;
IF length(trim(decision_reason))<5 OR length(payload::text)>30000 OR payload->>'key' !~ '^[a-z0-9][a-z0-9-]{1,99}$' OR length(trim(payload->>'title'))<2 THEN RAISE EXCEPTION 'Content and a reason are required'; END IF;
IF coalesce(payload->>'href','')<>'' AND NOT (payload->>'href' ~ '^/[^/]' OR payload->>'href' ~ '^(https://|mailto:|tel:)') THEN RAISE EXCEPTION 'Unsupported content link'; END IF;
IF publish_content THEN
IF k='home_section' AND ((c<>'' AND position(lower(c) IN label)=0) OR (cat<>'' AND position(replace(lower(cat),'-',' ') IN label)=0)) THEN RAISE EXCEPTION 'Section label must match city and category criteria'; END IF;
IF k='testimonial' AND (coalesce(payload->>'source','')='' OR coalesce((payload->>'approval')::boolean,false)=false) THEN RAISE EXCEPTION 'Testimonial provenance and approval required'; END IF;
IF k='banner' AND coalesce(payload->>'image','') !~ '^https://' THEN RAISE EXCEPTION 'Banner requires an approved HTTPS image'; END IF;
IF k='redirect' AND (payload->>'body' !~ '^/[^/]' OR payload->>'href' !~ '^/[^/]' OR payload->>'body'=payload->>'href') THEN RAISE EXCEPTION 'Redirect must have distinct local paths'; END IF;
IF k='location_page' THEN SELECT count(*) INTO matches FROM public.businesses b WHERE b.status='approved' AND b.archived_at IS NULL AND b.city=c AND (cat='' OR b.category=cat) AND (coalesce(payload->>'locality','')='' OR b.area=payload->>'locality'); IF length(trim(payload->>'body'))<300 OR matches<3 THEN RAISE EXCEPTION 'Location pages require useful content and at least three approved matching listings'; END IF; END IF;
END IF;
INSERT INTO public.site_content(key,kind,draft) VALUES(payload->>'key',k,payload) ON CONFLICT(key) DO UPDATE SET draft=excluded.draft,kind=excluded.kind,updated_at=now() RETURNING id,revision+1 INTO cid,rev;
UPDATE public.site_content SET revision=rev,published=CASE WHEN publish_content THEN payload ELSE published END,published_at=CASE WHEN publish_content THEN now() ELSE published_at END WHERE id=cid;
INSERT INTO public.content_revisions(content_id,revision,payload,action,actor_id,reason) VALUES(cid,rev,payload,CASE WHEN publish_content THEN 'publish' ELSE 'draft' END,auth.uid(),decision_reason); RETURN cid; END; $$;
REVOKE ALL ON FUNCTION public.save_site_content(jsonb,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_site_content(jsonb,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.unpublish_site_content(cid uuid, decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.content_permission() OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Content management and reason required'; END IF; UPDATE public.site_content SET published=NULL,published_at=NULL,revision=revision+1 WHERE id=cid; INSERT INTO public.content_revisions(content_id,revision,payload,action,actor_id,reason) SELECT id,revision,draft,'unpublish',auth.uid(),decision_reason FROM public.site_content WHERE id=cid; END; $$;
REVOKE ALL ON FUNCTION public.unpublish_site_content(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.unpublish_site_content(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.public_content() RETURNS TABLE(key text,kind text,payload jsonb,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT key,kind,published,published_at FROM public.site_content WHERE published IS NOT NULL AND kind<>'redirect'; $$;
GRANT EXECUTE ON FUNCTION public.public_content() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.effective_business_plan(bid uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT jsonb_build_object('key',p.key,'entitlements',p.entitlements,'ends_at',s.ends_at) FROM public.business_subscriptions s JOIN public.plan_definitions p ON p.id=s.plan_id WHERE s.business_id=bid AND s.status='active' AND s.starts_at<=now() AND s.ends_at>now() AND p.active ORDER BY s.ends_at DESC LIMIT 1),'{"key":"free","entitlements":{}}'::jsonb); $$;
GRANT EXECUTE ON FUNCTION public.effective_business_plan(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.public_placements(selected_city text,selected_category text DEFAULT '',selected_placement text DEFAULT 'search') RETURNS TABLE(id uuid,business_id uuid,creative text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.business_id,p.creative FROM public.sponsored_placements p JOIN public.businesses b ON b.id=p.business_id WHERE b.status='approved' AND b.archived_at IS NULL AND b.city=selected_city AND p.city=selected_city AND p.approved AND p.status='active' AND p.starts_at<=now() AND p.ends_at>now() AND p.placement=selected_placement AND (p.category='' OR p.category=selected_category) ORDER BY p.starts_at,p.id LIMIT 2; $$;
GRANT EXECUTE ON FUNCTION public.public_placements(text,text,text) TO anon,authenticated;
COMMENT ON COLUMN public.businesses.plan IS 'DEPRECATED as entitlement authority: use effective_business_plan and dated business_subscriptions; retained for legacy display';
COMMENT ON COLUMN public.businesses.sponsored IS 'DEPRECATED as placement authority: use approved targeted dated sponsored_placements';